using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileReductionTrial{static CityMobileReductionTrial(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityMobileReductionTrial.request"))return;File.Delete("CityMobileReductionTrial.request");try{var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var fs=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh&&!f.GetComponentInParent<LODGroup>()&&f.GetComponent<MeshRenderer>());var s=new StringBuilder();foreach(var group in fs.GroupBy(f=>f.sharedMesh).OrderByDescending(g=>g.Count()*CityMobileMeshReducer.Triangles(g.Key)).Take(35)){var m=group.Key;s.Append(m.name+" x"+group.Count()+" base="+CityMobileMeshReducer.Triangles(m));for(int level=1;level<=2;level++){var reduced=CityMobileMeshReducer.Reduce(m,level);s.Append(" LOD"+level+"="+(reduced?CityMobileMeshReducer.Triangles(reduced).ToString():"unchanged "+CityMobileMeshReducer.LastReason));if(reduced)UnityEngine.Object.DestroyImmediate(reduced);}s.AppendLine();}File.WriteAllText("FinalEnvironmentRoadReview/MobileReductionTrial.txt",s.ToString());}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MobileReductionTrial.txt",e.ToString());}}}
